-- =============================================================================
-- V1 — Baseline
--
-- Establishes the schema that every later migration builds on. Business tables
-- arrive with the modules that own them:
--
--   V2  identity + organization   (M2, M3)
--   V3  reporting catalogue       (M4)
--   V4  submission                (M6)
--   V5  imports                   (M7)
--
-- Conventions fixed here and applied by every later migration:
--   * snake_case, singular table names, *_id foreign keys
--   * uuid primary keys (UUIDv7, generated by the application)
--   * timestamptz for instants, date for calendar values, numeric(18,4) for metrics
--   * text + CHECK for enumerations, never a native PostgreSQL enum: extending
--     one needs ALTER TYPE, which is awkward to do safely in a migration
--   * every mutable table carries created_at/created_by, updated_at/updated_by
--     and a version column for optimistic locking
--
-- Migrations are immutable once merged. Schema changes go forward only, and a
-- destructive change is split across releases (expand, backfill, contract).
-- =============================================================================

CREATE SCHEMA IF NOT EXISTS opsflow;

COMMENT ON SCHEMA opsflow IS
    'OpsFlow business tables. Spring Batch metadata is kept out of here, in its own batch schema (M7).';
